import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test("Upload a document", { tag: "@DOC-01" }, async ({ apiAs }) => {
  // Arrange: a draft vendor owned by the member's tenant
  const member = await apiAs("member");
  const created = await member.post("/api/vendors", {
    data: {
      name: uniqueName("Doc Vendor"),
      category: "services",
      contact_email: `doc-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@example.com`,
    },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = await created.json();
  expect(vendor.status).toBe("draft");

  // Act: upload the insurance certificate as multipart form data
  const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: {
      kind: "insurance_certificate",
      file: {
        name: "insurance_certificate.txt",
        mimeType: "text/plain",
        buffer: readFileSync(sample("insurance_certificate.txt")),
      },
    },
  });

  // Assert: response status and processing state
  expect(response.status(), await response.text()).toBe(201);
  const document = await response.json();
  expect(document.status).toBe("processing");
  expect(document.vendor_id).toBe(vendor.id);
  expect(document.kind).toBe("insurance_certificate");

  // Assert: audit event recorded (poll in case it is written asynchronously)
  await expect
    .poll(
      async () => {
        const audit = await member.get(`/api/vendors/${vendor.id}/audit`);
        expect(audit.status(), await audit.text()).toBe(200);
        const body = (await audit.json()) as { items: { action: string }[] };
        return body.items.map((event) => event.action);
      },
      { timeout: 15_000 },
    )
    .toContain("document.uploaded");
});
